'use strict';
window.TravelMaps=(()=>{
const jobs={};
const providerFor=country=>country==='KR'?'naver':'google';
function load(provider,key){if(provider==='google'&&window.google?.maps?.Map)return Promise.resolve();if(provider==='naver'&&window.naver?.maps?.Map)return Promise.resolve();if(jobs[provider])return jobs[provider];jobs[provider]=new Promise((resolve,reject)=>{const script=document.createElement('script'),callback='travelMapReady_'+provider;const timer=setTimeout(()=>reject(Error('Map connection timed out.')),15000);window[callback]=()=>{clearTimeout(timer);resolve()};script.onerror=()=>{clearTimeout(timer);reject(Error('The map service could not load.'))};script.src=provider==='google'?`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(key)}&loading=async&callback=${callback}&v=weekly`:`https://oapi.map.naver.com/openapi/v3/maps.js?ncpKeyId=${encodeURIComponent(key)}&callback=${callback}`;script.async=true;document.head.appendChild(script)});return jobs[provider]}
async function create({element,country,center,points,selected,onSelect,position}){const provider=providerFor(country),config=window.TRAVEL_MAP_CONFIG||{},key=provider==='google'?config.googleMapsApiKey:config.naverMapsClientId;if(!key)return null;await load(provider,key);if(!element.isConnected)return null;const overlays=[];let native;
if(provider==='google'){const g=google.maps;native=new g.Map(element,{center,zoom:14,mapTypeControl:false,streetViewControl:false,fullscreenControl:false});const bounds=new g.LatLngBounds();points.forEach((p,i)=>{const marker=new g.Marker({map:native,position:p,title:p.name,label:{text:String(i+1),color:'white'},icon:{path:g.SymbolPath.CIRCLE,scale:15,fillColor:p.id===selected?'#e88654':'#184c42',fillOpacity:1,strokeColor:'white',strokeWeight:3}});marker.addListener('click',()=>onSelect(p.id));overlays.push(marker);bounds.extend(p)});if(points.length>1){overlays.push(new g.Polyline({map:native,path:points,strokeOpacity:0,icons:[{icon:{path:'M 0,-1 0,1',strokeOpacity:1,strokeColor:'#184c42',scale:3},offset:'0',repeat:'15px'}]}));native.fitBounds(bounds,65)}else if(points.length)native.setCenter(points[0]);if(position)overlays.push(new g.Marker({map:native,position,title:'My location',icon:{path:g.SymbolPath.CIRCLE,scale:8,fillColor:'#357ddd',fillOpacity:1,strokeColor:'white',strokeWeight:3}}));return{provider,remove(){overlays.forEach(o=>o.setMap(null));g.event.clearInstanceListeners(native)}}}
const n=naver.maps;native=new n.Map(element,{center:new n.LatLng(center.lat,center.lng),zoom:14,zoomControl:true,zoomControlOptions:{position:n.Position.BOTTOM_RIGHT}});const coords=points.map(p=>new n.LatLng(p.lat,p.lng));points.forEach((p,i)=>{const marker=new n.Marker({map:native,position:coords[i],title:p.name,icon:{content:`<div class="map-marker ${p.id===selected?'selected':''}">${i+1}</div>`,anchor:new n.Point(16,16)}});n.Event.addListener(marker,'click',()=>onSelect(p.id));overlays.push(marker)});if(coords.length>1){overlays.push(new n.Polyline({map:native,path:coords,strokeColor:'#184c42',strokeWeight:3,strokeStyle:'shortdash'}));native.fitBounds(n.LatLngBounds.bounds(...coords),{top:65,right:65,bottom:65,left:65})}else if(coords.length)native.setCenter(coords[0]);if(position)overlays.push(new n.Marker({map:native,position:new n.LatLng(position.lat,position.lng),title:'My location'}));const observer=new ResizeObserver(()=>native.setSize(new n.Size(element.clientWidth,element.clientHeight)));observer.observe(element);return{provider,remove(){observer.disconnect();overlays.forEach(o=>o.setMap(null));native.destroy()}}}
return{providerFor,create};})();
